// The launch screen is the app's sand with the mark, light and dark, on both
// platforms. It was Flutter's template: a 1×1 transparent image on white on
// iOS, and black on Android in dark mode — a flash of the wrong colour before
// the first frame. Generated by flutter_native_splash (pubspec.yaml); this
// holds what it must have produced.
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

String read(String p) => File(p).readAsStringSync();

void main() {
  const res = 'android/app/src/main/res';

  test('Android 12+: sand ground and the mark, in light and dark', () {
    for (final dir in ['values-v31', 'values-night-v31']) {
      final xml = read('$res/$dir/styles.xml');
      expect(
        xml,
        contains('windowSplashScreenBackground">#fdfaf3<'),
        reason: dir,
      );
      expect(xml, contains('@drawable/android12splash'), reason: dir);
    }
  });

  test('older Android: the launch drawable is the sand and the mark', () {
    for (final f in [
      'drawable/launch_background.xml',
      'drawable-v21/launch_background.xml',
      'drawable-night/launch_background.xml',
      'drawable-night-v21/launch_background.xml',
    ]) {
      final xml = read('$res/$f');
      expect(xml, contains('@drawable/background'), reason: f);
      expect(xml, contains('@drawable/splash'), reason: f);
    }
  });

  test('iOS: the storyboard fills with the sand and centres the mark', () {
    final sb = read('ios/Runner/Base.lproj/LaunchScreen.storyboard');
    expect(sb, contains('image="LaunchBackground"'));
    expect(sb, contains('image="LaunchImage"'));
    // The template's own launch image was a 1×1 transparent placeholder.
    expect(
      File('ios/Runner/Assets.xcassets/LaunchImage.imageset/LaunchImage@3x.png')
          .lengthSync(),
      greaterThan(1000),
    );
  });

  test('the orientation lock survived the generator', () {
    // flutter_native_splash rewrites the manifest and dropped
    // screenOrientation the first time it ran; the manifest was restored.
    expect(
      read('android/app/src/main/AndroidManifest.xml'),
      contains('android:screenOrientation="portrait"'),
    );
  });
}
